{
  "id": "V028",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "운송비 검토 부담을 줄이고 청구 항목을 검토하려는 목적이 반영됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "청구 항목별 금액을 합의된 요율과 비교하는 행동이 반영됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "화물 청구서의 항목과 합의된 요율이 모두 언급됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "청구 항목별 금액과 합의된 요율이 비교 입력으로 반영됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "과다 청구 의심 부분과 비교 근거를 검토 목록에 남기는 요구가 반영됨."
    },
    {
      "field": "constraints",
      "score": 0,
      "reason": "자동 수정·지급 금지와 담당자의 확인 후 처리 조건이 모든 뷰에서 빠짐."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가한 표현은 없음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "운송비 검토 담당자의 역할과 담당자가 확인할 목록이라는 점이 반영됨."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "청구서를 자동으로 수정하거나 대금을 지급하지 않고 담당자가 확인한 뒤 처리합니다.",
      "view_quote": "",
      "reason": "자동 수정·지급 금지 및 담당자 확인 후 처리 조건이 모든 뷰에서 누락됨."
    }
  ],
  "permission_interpretation": "원문은 자동 수정과 지급을 금지하고 담당자의 확인 후 처리를 요구함. AI가 수정·지급한다거나 담당자가 매번 반드시 두 작업을 모두 수행한다는 뜻은 아님."
}
